  width: 26px !important;
  max-width: 26px !important;
  flex: 0 0 26px !important;
  overflow: hidden !important;
}

.voice-waveform-bar {
  width: 3px !important;
  min-width: 3px !important;
  border-radius: 999px !important;
}

/* 秒数紧紧挨着第 4 根波浪，气泡自动贴着秒数收口！ */
.voice-duration {
